import Config

config :firmowid, Firmowid.Ash.Currencies.Converter, rates_provider: :api

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :firmowid, FirmowidWeb.Core.Endpoint,
  cache_static_manifest: "priv/static/cache_manifest.json",
  http: [port: {:system, "PORT"}],
  url: [host: "firmowid.pl", port: 80],
  check_origin: ["https://firmowid.pl", "https://staging.firmowid.pl"],
  force_ssl: [
    hsts: true,
    preload: true,
    subdomains: true,
    rewrite_on: [:x_forwarded_host, :x_forwarded_port, :x_forwarded_proto],
    exclude: ["localhost", "127.0.0.1"]
  ]

# Do not print debug messages in production
config :logger, level: :info

config :sentry,
  dsn: "https://dc33e5660f563be6b0423120825f8da3@o4511195748630528.ingest.de.sentry.io/4511195751317584",
  environment_name: "production",
  in_app_otp_apps: [:firmowid],
  enable_source_code_context: true,
  root_source_code_paths: [File.cwd!()],
  before_send_log: {Firmowid.SentryFilter, :before_send_log},
  enable_logs: true,
  logs: [
    level: :info,
    metadata: [:request_id, :user_id, :health_check]
  ],
  integrations: [
    oban: [
      capture_errors: true,
      cron: [enabled: false]
    ]
  ]

